jsCode:
const el = document.getElementById('container');
el.style.cssText = 'position:relative;width:100%;height:100%;overflow:hidden;background:#000;';

const sparks = [];
function getSize() {
  return { W: el.clientWidth || 350, H: el.clientHeight || 400 };
}

function createSpark() {
  const {W, H} = getSize();
  const s = document.createElement('div');
  s.className = 'spark';
  const size = Math.random() * 14 + 4;
  const x = W / 2 + (Math.random() - 0.5) * 80;
  const data = {
    el: s, x, y: H * 0.8,
    vx: (Math.random() - 0.5) * 3,
    vy: -(Math.random() * 5 + 2),
    life: 1, decay: Math.random() * 0.018 + 0.012,
    size, hue: Math.random() * 40
  };
  s.style.cssText = `position:absolute;border-radius:50%;mix-blend-mode:screen;width:${size}px;height:${size}px;left:${x}px;top:${H*0.8}px;`;
  el.appendChild(s);
  sparks.push(data);
}

function animate() {
  const {H} = getSize();
  for (let i = sparks.length - 1; i >= 0; i--) {
    const s = sparks[i];
    s.life -= s.decay;
    s.x += s.vx; s.y += s.vy;
    s.vy -= 0.06; s.vx *= 0.99;
    if (s.life <= 0) { s.el.remove(); sparks.splice(i,1); continue; }
    s.el.style.cssText = `position:absolute;border-radius:50%;mix-blend-mode:screen;
      width:${s.size}px;height:${s.size}px;
      left:${s.x}px;top:${s.y}px;
      background:hsl(${s.hue},100%,${50+s.life*30}%);
      opacity:${s.life};transform:scale(${s.life});
      box-shadow:0 0 ${s.size*2}px hsl(${s.hue},100%,60%);`;
  }
  if (Math.random() < 0.7) createSpark();
  requestAnimationFrame(animate);
}
animate();

