html, body, #container {
  margin: 0; width: 100%; height: 100%;
  background: #050008; overflow: hidden;
}
canvas { display: block; }

jsCode:
const el = document.getElementById('container');
const c = document.createElement('canvas');
const ctx = c.getContext('2d');
c.width = el.offsetWidth || 400;
c.height = el.offsetHeight || 500;
el.appendChild(c);
const W = c.width, H = c.height;
let offset = 0;

function drawGrid() {
  ctx.fillStyle = '#050008';
  ctx.fillRect(0, 0, W, H);

  // Horizon glow
  const grd = ctx.createLinearGradient(0, H * 0.45, 0, H * 0.6);
  grd.addColorStop(0, 'rgba(236,72,153,0.6)');
  grd.addColorStop(1, 'transparent');
  ctx.fillStyle = grd;
  ctx.fillRect(0, H * 0.45, W, H * 0.15);

  const horizon = H * 0.5;
  const vp = { x: W / 2, y: horizon };
  const cols = 12;
  const step = W / cols;

  ctx.lineWidth = 1;

  // Vertical lines
  for (let i = 0; i <= cols; i++) {
    const x = i * step;
    ctx.beginPath();
    ctx.moveTo(x, horizon);
    ctx.lineTo(vp.x + (x - vp.x) * 0.01, horizon);
    const alpha = 1 - Math.abs(i - cols / 2) / (cols / 2) * 0.6;
    ctx.strokeStyle = `rgba(236,72,153,${alpha})`;
    ctx.shadowColor = '#ec4899';
    ctx.shadowBlur = 4;
    ctx.stroke();

    ctx.beginPath();
    ctx.moveTo(x, H);
    ctx.lineTo(vp.x, horizon);
    ctx.strokeStyle = `rgba(167,139,250,${alpha * 0.8})`;
    ctx.shadowColor = '#a78bfa';
    ctx.shadowBlur = 4;
    ctx.stroke();
  }

  // Horizontal lines with perspective
  const rows = 10;
  for (let i = 0; i < rows; i++) {
    const t = (i / rows + offset) % 1;
    const ease = t * t;
    const y = horizon + (H - horizon) * ease;
    const alpha = ease * 0.9 + 0.1;
    ctx.beginPath();
    ctx.moveTo(0, y);
    ctx.lineTo(W, y);
    ctx.strokeStyle = `rgba(167,139,250,${alpha})`;
    ctx.shadowColor = '#a78bfa';
    ctx.shadowBlur = 3;
    ctx.stroke();
  }

  // Sun
  const sunGrd = ctx.createRadialGradient(W/2, horizon, 0, W/2, horizon, 60);
  sunGrd.addColorStop(0, 'rgba(251,191,36,0.9)');
  sunGrd.addColorStop(0.4, 'rgba(236,72,153,0.7)');
  sunGrd.addColorStop(1, 'transparent');
  ctx.beginPath();
  ctx.arc(W/2, horizon, 60, 0, Math.PI * 2);
  ctx.fillStyle = sunGrd;
  ctx.fill();

  offset = (offset + 0.004) % 1;
  requestAnimationFrame(drawGrid);
}
drawGrid();
